[TestFixture]
public class FirstUniqueLetterTests
{
    [Test]
    public void Returns_First_Unique_Letter()
    {
        var result = FirstUniqueLetter("Swiss");
        Assert.That(result, Is.EqualTo('w'));
    }

    private char? FirstUniqueLetter(string name)
    {
        var counts = new Dictionary<char, int>();
        var normalized = name.ToLowerInvariant();

        foreach (var ch in normalized)
        {
            if (!char.IsLetter(ch))
                continue;

            counts[ch] = counts.GetValueOrDefault(ch) + 1;
        }

        foreach (var ch in normalized)
        {
            if (char.IsLetter(ch) && counts[ch] == 1)
                return ch;
        }

        return null;
    }
}
